CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','monitor')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('site','building','level')), parent_id uuid REFERENCES locations(id), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS gateways(id text PRIMARY KEY CHECK(id ~ '^[a-zA-Z0-9_-]{1,64}$'), name text NOT NULL, location_id uuid REFERENCES locations(id), active boolean NOT NULL DEFAULT true, mqtt_hash text NOT NULL, online boolean NOT NULL DEFAULT false, last_seen timestamptz, boot_id text, report_interval_s integer NOT NULL DEFAULT 60 CHECK(report_interval_s BETWEEN 5 AND 86400));
CREATE TABLE IF NOT EXISTS profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, chemistry text NOT NULL, nominal_mv integer NOT NULL CHECK(nominal_mv > 0), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS profile_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES profiles(id), version integer NOT NULL, thresholds jsonb NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(profile_id,version));
CREATE TABLE IF NOT EXISTS lamps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gateway_id text NOT NULL REFERENCES gateways(id), device_id text NOT NULL, name text, model text NOT NULL DEFAULT '', nominal_mv integer, location_id uuid REFERENCES locations(id), place text NOT NULL DEFAULT '', x double precision, y double precision, profile_version_id uuid REFERENCES profile_versions(id), desired_version integer NOT NULL DEFAULT 0, applied_version integer, config_capable boolean NOT NULL DEFAULT false, last_seen timestamptz, latest jsonb, latest_boot text, latest_uptime bigint, latest_measured_at timestamptz, report_interval_s integer NOT NULL DEFAULT 60, UNIQUE(gateway_id,device_id));
CREATE TABLE IF NOT EXISTS messages(gateway_id text NOT NULL REFERENCES gateways(id), message_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(gateway_id,message_id));
CREATE TABLE IF NOT EXISTS measurements(id bigserial PRIMARY KEY, lamp_id uuid NOT NULL REFERENCES lamps(id), received_at timestamptz NOT NULL DEFAULT now(), measured_at timestamptz, data jsonb NOT NULL, location_snapshot jsonb NOT NULL, config_version integer, profile_snapshot jsonb);
CREATE INDEX IF NOT EXISTS measurements_lamp_time ON measurements(lamp_id,received_at);
CREATE TABLE IF NOT EXISTS test_reports(id bigserial PRIMARY KEY, lamp_id uuid NOT NULL REFERENCES lamps(id), received_at timestamptz NOT NULL DEFAULT now(), measured_at timestamptz, data jsonb NOT NULL, location_snapshot jsonb NOT NULL, config_version integer, profile_snapshot jsonb);
CREATE INDEX IF NOT EXISTS tests_lamp_time ON test_reports(lamp_id,received_at);
CREATE TABLE IF NOT EXISTS commands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lamp_id uuid NOT NULL REFERENCES lamps(id), version integer NOT NULL, profile_version_id uuid NOT NULL REFERENCES profile_versions(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','deferred','applied','rejected','superseded')), reason text, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), applied_at timestamptz, UNIQUE(lamp_id,version));
CREATE TABLE IF NOT EXISTS plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), level_id uuid NOT NULL REFERENCES locations(id), filename text NOT NULL, source text NOT NULL, geometry jsonb NOT NULL, warnings jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_plan ON plans(level_id) WHERE active;
CREATE TABLE IF NOT EXISTS audits(id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), action text NOT NULL, target text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS retired_boots(lamp_id uuid NOT NULL REFERENCES lamps(id), boot_id text NOT NULL, PRIMARY KEY(lamp_id,boot_id));
